use super::*;
#[test]
fn sqlite_snapshot_epw_authored_grammar_and_protocol_admit_complete_logical_records(){let grammar=dsl::parse_grammar(include_str!("../../📝️text/📖️.grammar.semio")).unwrap();let recognizer=dsl::Recognizer::compile(&grammar);for snapshot in[fixture(),EpwSnapshot::default(),crate::standards::energyplus::subsets::any::io::decode_epw(include_str!("../../../../🖼️assets/🎬️demo/🧪️example/🌦️.epw")).unwrap()]{let text=<EpwSnapshot as store::ArtifactDsl>::print_dsl(&snapshot);let (_,body)=store::semio_format::split_text_preamble(&text).unwrap();assert!(recognizer.recognize(body).unwrap(),"{body}");}let protocol=dsl::parse_protocol(include_str!("../../💾️binary/📡️.protocol.semio")).unwrap();assert_eq!(protocol.schema,"stdio.epw");assert_eq!(protocol.version,1);}

#[test]
fn sqlite_snapshot_epw_shipped_demo_assets_match_owned_native_source(){let snapshot=crate::standards::energyplus::subsets::any::io::decode_epw(include_str!("../../../../🖼️assets/🎬️demo/🧪️example/🌦️.epw")).unwrap();assert_eq!(<EpwSnapshot as store::ArtifactDsl>::parse_dsl(include_str!("../../../../📚️examples/🎬️demo/🖼️assets/🗣️.dsl.semio")).unwrap(),snapshot);assert_eq!(<EpwSnapshot as store::ArtifactPack>::decode_pack(include_bytes!("../../../../📚️examples/🎬️demo/🖼️assets/🎒️.pack.semio")).unwrap(),snapshot);}

use semio_framework_os_kernel::{sqlite_snapshot::{export_sqlite_database,import_sqlite_database,SqliteDatabaseLimits,SqliteSnapshotControl,SqliteValue,SqliteSnapshotPhase},ArtifactSqliteSnapshot};
fn fixture()->EpwSnapshot{store::json::from_json_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap()}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_epw_actual_erased_capability_preserves_binary_and_text(){use semio_framework_os_kernel::{io::{ArtifactDialect,IoPayload},sqlite_snapshot::SnapshotEncoding};let mut snapshot=fixture();snapshot.comments_1="comments,世界\nsecond line\0".into();snapshot.location.city="city,世界\n".into();semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("Epw erased SQLite").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let codec=store::document_codec(crate::STDIO_EPW_DOCUMENT_SCHEMA).await.unwrap().unwrap();let provider=codec.snapshot_sqlite.as_ref().unwrap();let dialect=ArtifactDialect{artifact_kind:"s.stdio.epw".into(),standard:"energyplus".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(<EpwSnapshot as store::ArtifactPack>::encode_pack(&snapshot)),SnapshotEncoding::Text=>IoPayload::Text(<EpwSnapshot as store::ArtifactDsl>::print_dsl(&snapshot))};let database=(provider.export)(&codec.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(EpwSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),snapshot);let restored=(provider.import)(&codec.schema,&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(match restored{IoPayload::Binary(bytes)=><EpwSnapshot as store::ArtifactPack>::decode_pack(&bytes).unwrap(),IoPayload::Text(text)=><EpwSnapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap()},snapshot);}}
#[test]
fn sqlite_snapshot_epw_owned_encoding_preflight_checks_bounds_before_allocation(){use semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding;for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut snapshot=fixture();snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1024,..SqliteDatabaseLimits::default()})).unwrap_err().contains("native encoding exceeds file byte limit"));snapshot.comments_1="x".repeat(131073);let mut reached=false;assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |event|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>0{reached=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(reached);}}
fn roundtrip(snapshot:&EpwSnapshot)->EpwSnapshot{let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();EpwSnapshot::from_sqlite_database(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
#[test]
fn sqlite_snapshot_epw_full_neutral_fields_lexical_numbers_and_empty_collections(){let snapshot=fixture();assert_eq!(roundtrip(&snapshot),snapshot);let oracle:serde_json::Value=serde_json::from_str(&store::json::to_json_string(&protocol::ToValue::to_value(&snapshot))).unwrap();assert_eq!(oracle,serde_json::from_str::<serde_json::Value>(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap());let mut empty=EpwSnapshot::default();empty.schema="".into();assert_eq!(roundtrip(&empty),empty);}
#[test]
fn sqlite_snapshot_epw_independent_sqlite_joins_and_full_field_edits(){use std::{io::Write,process::{Command,Stdio}};let mut expected=fixture();let database=expected.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import {Database} from 'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const row=db.query('SELECT l.latitude,r.dry_bulb_temp,r.liquid_precip_quantity,p.records_per_hour FROM epw_document d JOIN epw_location l ON l.id=d.id JOIN epw_record r ON r.document_id=d.id JOIN epw_data_periods p ON p.id=d.id').get();if(row.latitude!=='+01.00'||row.dry_bulb_temp!=='20.0'||row.liquid_precip_quantity!=='35.0'||row.records_per_hour!==4294967295)throw Error('domain');db.run(\"UPDATE epw_record SET dry_bulb_temp='20.000',liquid_precip_quantity='edited 世界' WHERE id=1\");db.run(\"UPDATE epw_location SET elevation='-00.000' WHERE id=1\");db.run(\"UPDATE epw_data_period SET end_date='custom' WHERE id=2\");await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));expected.records[0].dry_bulb_temp="20.000".into();expected.records[0].liquid_precip_quantity="edited 世界".into();expected.location.elevation="-00.000".into();expected.data_periods.periods[1].end_date="custom".into();assert_eq!(EpwSnapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);}
#[test]
fn sqlite_snapshot_epw_refuses_invalid_owners_ordinals_widths_and_limits(){let snapshot=fixture();let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();for(table,column,value)in [("epw_record",1,SqliteValue::Integer(99)),("epw_record",2,SqliteValue::Integer(99)),("epw_data_period",1,SqliteValue::Integer(99)),("epw_data_period",2,SqliteValue::Integer(99)),("epw_data_periods",1,SqliteValue::Integer(4294967296)),("epw_record",37,SqliteValue::Integer(35))]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows[0].values[column]=value;assert!(EpwSnapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}for table in ["epw_location","epw_data_periods"]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows.clear();assert!(EpwSnapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:1,..SqliteDatabaseLimits::default()})).is_err());assert!(EpwSnapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:0,..SqliteDatabaseLimits::default()})).is_err());}
#[test]
fn sqlite_snapshot_epw_large_owned_text_and_entity_work_remain_cancellable(){let controls:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🎛️control.json")).unwrap();let mut snapshot=fixture();snapshot.records=vec![snapshot.records[0].clone();controls["entityCount"].as_u64().unwrap() as usize];let cancel_at=controls["cancelAt"].as_u64().unwrap() as usize;let mut reached=false;assert!(snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |event|{if event.completed>=cancel_at{reached=true;false}else{true}},SqliteDatabaseLimits::default())).is_err());assert!(reached);snapshot=fixture();snapshot.comments_1="x".repeat(controls["largeTextBytes"].as_u64().unwrap() as usize);let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();for phase in [SqliteSnapshotPhase::ProjectSnapshot,SqliteSnapshotPhase::ReconstructSnapshot]{let mut reached=false;let mut callback=|event:semio_framework_os_kernel::sqlite_snapshot::SqliteSnapshotProgress|{if event.phase==phase&&event.completed>0&&event.total==0{reached=true;false}else{true}};let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(if phase==SqliteSnapshotPhase::ProjectSnapshot{snapshot.to_sqlite_database(&mut control).is_err()}else{EpwSnapshot::from_sqlite_database(&database,&mut control).is_err()});assert!(reached);}}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_epw_actual_declaration_preserves_full_owned_intermediate_state(){use semio_framework_os_kernel::{io::{ArtifactDialect,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}},sqlite_snapshot::SnapshotEncoding};semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("EPW SQLite declaration").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();let snapshot=fixture();let dialect=ArtifactDialect{artifact_kind:"s.stdio.epw".into(),standard:"energyplus".into(),subset:"*".into()};let mut phases=Vec::new();let output=io_export_sqlite_snapshot(&dialect,&snapshot,SnapshotEncoding::Binary,SqliteDatabaseLimits::default(),&mut |event|{phases.push(event.phase);true}).await.unwrap();assert_eq!(io_import_sqlite_snapshot::<EpwSnapshot>(&dialect,&output.value,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value,snapshot);assert!(!phases.iter().any(|phase|matches!(phase,SqliteSnapshotPhase::EncodeNative|SqliteSnapshotPhase::DecodeNative)));}
